package ultra.downloads;
import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.json.*;import java.util.*;import android.app.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=28)
public class LikedPlaylistsTest {
 Activity c;
 @Before public void setup(){c=Robolectric.buildActivity(Activity.class).setup().get();app.revanced.extension.shared.utils.Utils.testContext=c;Library.prefs(c).edit().clear().commit();}
 Catalog.Playlist p(String id,String name){return new Catalog.Playlist("VL"+id,name,"https://i.ytimg.com/"+id);}
 Catalog.Track t(String id){return new Catalog.Track(id,id,"Singer","");}
 @Test public void allAliasesCollapseAtFirstLikedSlotWithOfficialNameAndArt()throws Exception{PlaylistIndex.roster(c,Arrays.asList(p("PLone","First"),p("PLalias","Liked Songs"),p("PLtwo","Other"),p("LM","Liked music"),p("PLalias2"," Liked MUSIC ")));assertEquals(Arrays.asList("LM","PLone","PLtwo"),new ArrayList<>(PlaylistIndex.groups(c).keySet())); /* DL21: Liked Music is a default pin the user can unpin, so it leads until then */assertEquals("Liked music",PlaylistIndex.groups(c).get("LM"));assertEquals("https://i.ytimg.com/LM",PlaylistIndex.art(c,"LM"));}
 @Test public void unionIncludesOldCacheAndAliasRoutesButDoesNotChangeSourceRows()throws Exception{PlaylistIndex.register("VLPLold","Liked Songs");PlaylistIndex.record("PLold",Arrays.asList(t("ccccccccccc")),true);PlaylistIndex.roster(c,Arrays.asList(p("LM","Liked music"),p("PLalias","Liked Songs")));PlaylistIndex.record("LM",Arrays.asList(t("aaaaaaaaaaa"),t("bbbbbbbbbbb")),true);PlaylistIndex.record("PLalias",Arrays.asList(t("bbbbbbbbbbb"),t("ddddddddddd")),true);String before=Library.prefs(c).getString("local_playlist_index","");assertEquals(4,PlaylistIndex.total(c,"LM"));assertEquals(PlaylistIndex.members(c,"LM"),PlaylistIndex.members(c,"VLPLalias"));assertEquals(Arrays.asList("aaaaaaaaaaa","bbbbbbbbbbb","ddddddddddd","ccccccccccc"),new ArrayList<>(PlaylistIndex.order(c,"LM").keySet()));assertEquals(before,Library.prefs(c).getString("local_playlist_index",""));assertEquals(1,PlaylistIndex.groups(c).size());assertTrue(PlaylistIndex.complete(c,"LM"));}
 @Test public void mergedRowsUseExistingLocalAudioAndMissingRows()throws Exception{PlaylistIndex.roster(c,Arrays.asList(p("LM","Liked music"),p("PLalias","Liked Songs")));PlaylistIndex.record("LM",Arrays.asList(t("aaaaaaaaaaa")),true);PlaylistIndex.record("PLalias",Arrays.asList(t("bbbbbbbbbbb")),true);Library.Item local=new Library.Item();local.id="bbbbbbbbbbb";local.state="done";local.uri="content://media/existing";ArrayList<Library.Item> rows=PlaylistIndex.ordered(c,"LM",Arrays.asList(local),true);assertEquals(2,rows.size());assertEquals("unavailable",rows.get(0).state);assertSame(local,rows.get(1));assertEquals("content://media/existing",local.uri);}
 @Test public void emptyAliasesDoNotMakeExtraRowsOrEraseSongs()throws Exception{PlaylistIndex.roster(c,Arrays.asList(p("LM","Liked music"),p("PLempty","Liked Songs"),p("PLempty2","Liked songs")));PlaylistIndex.record("LM",Arrays.asList(t("aaaaaaaaaaa")),true);assertEquals(1,PlaylistIndex.groups(c).size());assertEquals(1,PlaylistIndex.total(c,"LM"));assertFalse(PlaylistIndex.complete(c,"LM"));assertEquals(3,PlaylistIndex.rawGroups(c).size());}
 @Test public void genuineUnrelatedSameNamesAndSongDuplicatesStay()throws Exception{PlaylistIndex.roster(c,Arrays.asList(p("PLone","Other"),p("PLtwo","Other"),p("LM","Liked music")));PlaylistIndex.record("LM",Arrays.asList(t("aaaaaaaaaaa"),t("aaaaaaaaaaa")),true);assertEquals(3,PlaylistIndex.groups(c).size());assertEquals(2,PlaylistIndex.total(c,"LM"));}
 @Test public void emptyRosterDoesNotResurrectCachedLikedRows()throws Exception{PlaylistIndex.register("VLLM","Liked music");PlaylistIndex.roster(c,Collections.<Catalog.Playlist>emptyList());assertTrue(PlaylistIndex.groups(c).isEmpty());}
 @Test public void upgradeWorksOfflineWithOldPrefsAndNoRemoteSync()throws Exception{PlaylistIndex.register("VLLM","Liked Music");PlaylistIndex.register("VLPLold","Liked Songs");PlaylistIndex.record("LM",Arrays.asList(t("aaaaaaaaaaa")),true);PlaylistIndex.record("PLold",Arrays.asList(t("bbbbbbbbbbb")),true);PlaylistIndex.cached=null;assertEquals(1,PlaylistIndex.groups(c).size());assertEquals(2,PlaylistIndex.total(c,"LM"));}
 @Test public void nativeLibraryOrderOverridesCatalogOrderWithoutAlphabetizing()throws Exception{PlaylistIndex.roster(c,Arrays.asList(p("LM","Liked Music"),p("PLz","Z list"),p("PLa","A list")));PlaylistIndex.nativeOrder(Arrays.asList("LM","PLa","PLz"));assertEquals(Arrays.asList("LM","PLa","PLz"),new ArrayList<>(PlaylistIndex.groups(c).keySet()));PlaylistIndex.nativeOrder(Arrays.asList("LM","PLz","PLa"));assertEquals(Arrays.asList("LM","PLz","PLa"),new ArrayList<>(PlaylistIndex.groups(c).keySet()));}
 @Test public void catalogRefreshDoesNotUndoNativeNameAndCover()throws Exception{PlaylistIndex.registerNative("VLLM","Liked music","https://i.ytimg.com/native");PlaylistIndex.roster(c,Arrays.asList(p("LM","Liked Music")));assertEquals("Liked music",PlaylistIndex.groups(c).get("LM"));assertEquals("https://i.ytimg.com/native",PlaylistIndex.art(c,"LM"));}
 @Test public void tolerantIndexRetainsAvailableSongsButStrictBatchStillFails()throws Exception{org.json.JSONArray rows=new org.json.JSONArray().put(new org.json.JSONObject().put("playlistVideoRenderer",new org.json.JSONObject().put("videoId","aaaaaaaaaaa").put("title",new org.json.JSONObject().put("simpleText","One")))).put(new org.json.JSONObject().put("playlistVideoRenderer",new org.json.JSONObject().put("title",new org.json.JSONObject().put("simpleText","Unavailable"))));org.json.JSONObject body=new org.json.JSONObject().put("musicPlaylistShelfRenderer",new org.json.JSONObject().put("contents",rows));Catalog.Page readOnly=new Catalog.Page();readOnly.tolerant=true;Catalog.walk(body,readOnly,0);assertEquals(1,readOnly.ordered.size());assertTrue(readOnly.incomplete);try{Catalog.walk(body,new Catalog.Page(),0);fail();}catch(java.io.IOException expected){} }
}
